48b; } .cadenarota-result-item span:last-child { font-weight: 700; color: #0f172a; font-family: 'SF Mono', Monaco, monospace; } .cadenarota-result-highlight { background: #d1fae5; border: 1px solid #10b981; } .cadenarota-result-highlight span:last-child { color: #047857; } .cadenarota-result-cost { background: #dbeafe; border: 1px solid #3b82f6; } .cadenarota-result-cost span:last-child { color: #1e40af; } .cadenarota-history { margin-bottom: 24px; } .cadenarota-performance-chart { background: #ffffff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 24px; height: 320px; } .cadenarota-container .table { color: #334155; background: #ffffff; } .cadenarota-container .table th { background: #f1f5f9; color: #1e40af; border-color: #e2e8f0; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.05em; font-weight: 700; } .cadenarota-container .table td { border-color: #e2e8f0; color: #475569; } .cadenarota-container .table-striped tbody tr:nth-of-type(odd) { background: #f8fafc; }
/* EQIL 2026-11-03: briefing, hints, cost breakdown, debrief, focus, contrast, reduced motion */
.cadenarota-briefing { background: #f8fafc; border-left: 4px solid #1d4ed8; border-radius: 8px; padding: 12px 16px; margin: 0 0 16px; color: #1e293b; }
.cadenarota-briefing h3 { margin: 0 0 6px; font-size: 1rem; color: #1e3a8a; }
