.cadenarota-container select, .cadenarota-container option { color-scheme: light; background-color: #ffffff; color: #0f172a; }
.cadenarota-cm { text-align: left; color: #0f172a; }
.cadenarota-cm h2 { font-size: 1.3rem; margin: 0 0 8px; }
